async function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms))
}

async function httpRequest({ method, url, token, body }) {
    const headers = {
        "Content-Type": "application/json",
    }

    if (token) {
        headers.Authorization = `Bearer ${token}`
    }

    const res = await fetch(url, {
        method,
        headers,
        body: body ? JSON.stringify(body) : undefined,
    })

    const text = await res.text()

    let data
    try {
        data = JSON.parse(text)
    } catch {
        data = text
    }

    if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${JSON.stringify(data)}`)
    }

    return data
}

// -------------------- CREATE FLOW --------------------

async function createTasks() {
    console.log("\n=== CREATE TASKS ===")

    for (let i = 0; i < CONFIG.payloads.length; i++) {
        const payload = CONFIG.payloads[i]

        console.log(`Create ${i + 1}/${CONFIG.payloads.length}`)

        if (CONFIG.dryRun) {
            console.log(payload)
            continue
        }

        try {
            await httpRequest({
                method: "POST",
                url: CONFIG.baseUrl + CONFIG.createEndpoint,
                token: CONFIG.userToken,
                body: payload,
            })

            console.log("Created")
        } catch (err) {
            console.error("Create failed:", err.message)
        }

        await sleep(CONFIG.delayMs)
    }
}

// -------------------- REJECT FLOW --------------------

async function rejectAllTasks() {
    console.log("\n=== REJECT ALL TASKS ===")

    // 1. Fetch list
    const list = await httpRequest({
        method: "GET",
        url: CONFIG.baseUrl + CONFIG.listEndpoint,
        token: CONFIG.adminToken,
    })

    // ⚠️ Adjust this depending on API shape
    const tasks = Array.isArray(list) ? list : list?.data || []

    console.log(`Found ${tasks.length} tasks`)

    // 2. Loop & reject
    for (let i = 0; i < tasks.length; i++) {
        const task = tasks[i]

        const payload = {
            id: task.id,
            object: {},
            remark: null,
            taskAction: "reject",
        }

        console.log(`Reject ${i + 1}/${tasks.length} → ${task.id}`)

        if (CONFIG.dryRun) {
            console.log(payload)
            continue
        }

        try {
            await httpRequest({
                method: "POST",
                url: CONFIG.baseUrl + CONFIG.submitEndpoint,
                token: CONFIG.adminToken,
                body: payload,
            })

            console.log("Rejected")
        } catch (err) {
            console.error("Reject failed:", err.message)
        }

        await sleep(CONFIG.delayMs)
    }
}

// -------------------- MAIN --------------------

async function main() {
    console.log("RW Kinerja Script")

    if (!CONFIG.dryRun) {
        if (!CONFIG.adminToken) {
            throw new Error("adminToken is required for reject flow")
        }
    }

    // Step 1: create (optional)
    await createTasks()

    // Step 2: reject all
    await rejectAllTasks()

    console.log("\n=== DONE ===")
}

main().catch((err) => {
    console.error("Fatal:", err.message)
    process.exit(1)
})
